const upsertDonor = `-- name: UpsertDonor :one
INSERT INTO blood_donors (user_id, blood_group, available, phone, last_donated)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (user_id) DO UPDATE
SET blood_group = EXCLUDED.blood_group, available = EXCLUDED.available,
    phone = EXCLUDED.phone, last_donated = EXCLUDED.last_donated, updated_at = now()
RETURNING user_id, blood_group, available, phone, last_donated, donations, created_at, updated_at
`

type UpsertDonorParams struct {
	UserID      uuid.UUID
	BloodGroup  string
	Available   bool
	Phone       string
	LastDonated *time.Time
}

func (q *Queries) UpsertDonor(ctx context.Context, arg UpsertDonorParams) (BloodDonor, error) {
	row := q.db.QueryRow(ctx, upsertDonor,
		arg.UserID,
		arg.BloodGroup,
		arg.Available,
		arg.Phone,
		arg.LastDonated,
	)
	var i BloodDonor
	err := row.Scan(
		&i.UserID,
		&i.BloodGroup,
		&i.Available,
		&i.Phone,
		&i.LastDonated,
		&i.Donations,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
